"""Patients, consents and family links in the admin.

* Patients are VIEW-ONLY here: the code is generated by the server and demographics belong to the owning clinician
  (API). Nobody can add or delete a patient (Patient is PROTECT-referenced by analysis runs).
* Consents and family links are history: no add / edit / delete. The only change possible is the same one the API
  offers, done through the SAME service code (revoke a consent, switch a family link off), and it is audited.
* Opening a record or a list writes an AuditLog row (core.admin_base.PatientDataAdminMixin).
"""
from django.contrib import admin, messages
from django.db import transaction
from django.db.models import Count, Exists, OuterRef
from django.utils.html import format_html, format_html_join
from rest_framework.exceptions import NotFound

from apps.audit import services as audit
from core.admin_base import BaseModelAdmin, PatientDataAdminMixin, display

from . import consent_banner, services
from .models import Consent, FamilyLink, Patient


def _can_change_access(request) -> bool:
    user = request.user
    return bool(user.is_active and user.is_staff and (user.is_superuser or getattr(user, "role", "") == "admin"))


class AnalysisConsentFilter(admin.SimpleListFilter):
    title = "analysis consent"
    parameter_name = "analysis_consent"

    def lookups(self, request, model_admin):
        return (("active", "Active"), ("not_active", "Missing or revoked"))

    def queryset(self, request, queryset):
        if self.value() == "active":
            return queryset.filter(_analysis_consent=True)
        if self.value() == "not_active":
            return queryset.filter(_analysis_consent=False)
        return queryset


@admin.register(Patient)
class PatientAdmin(PatientDataAdminMixin, BaseModelAdmin):
    list_display = ("patient_code", "name", "owner", "analysis_consent", "medication_total", "created_at")
    list_filter = (AnalysisConsentFilter, "sex")
    search_fields = ("patient_code", "name", "owner__email")
    list_select_related = ("owner",)
    ordering = ("-created_at", "-id")
    readonly_fields = ("patient_code", "name", "owner", "birth_year", "sex", "weight_kg", "created_at", "consent_state")
    fieldsets = (
        (None, {"fields": ("patient_code", "name", "owner", "birth_year", "sex", "weight_kg", "created_at")}),
        ("Consent state (as the banner shows it)", {"fields": ("consent_state",)}),
    )

    def get_queryset(self, request):
        active = Consent.objects.filter(patient=OuterRef("pk"), scope=services.ANALYSIS_SCOPE, revoked_at__isnull=True)
        return super().get_queryset(request).annotate(
            _analysis_consent=Exists(active), _medication_total=Count("medications", distinct=True))

    @display(description="Analysis consent", boolean=True, ordering="_analysis_consent")
    def analysis_consent(self, obj):
        return obj._analysis_consent

    @display(description="Medicines", ordering="_medication_total")
    def medication_total(self, obj):
        return obj._medication_total

    @display(description="Consent state")
    def consent_state(self, obj):
        banner = consent_banner.consent_banner(obj)
        rows = [(s["label_en"], s["status"].upper()) for s in banner["scopes"]]
        return format_html("<div><strong>{}</strong></div>{}", banner["message_en"],
                           format_html_join("", "<div>{}: {}</div>", rows))

    def has_add_permission(self, request):
        return False

    def has_change_permission(self, request, obj=None):
        return False

    def has_delete_permission(self, request, obj=None):
        return False


# ------------------------------------------------------------------------------------------------ consents
class ConsentStatusFilter(admin.SimpleListFilter):
    title = "status"
    parameter_name = "state"

    def lookups(self, request, model_admin):
        return (("active", "Active"), ("revoked", "Revoked"))

    def queryset(self, request, queryset):
        if self.value() == "active":
            return queryset.filter(revoked_at__isnull=True)
        if self.value() == "revoked":
            return queryset.filter(revoked_at__isnull=False)
        return queryset


@admin.register(Consent)
class ConsentAdmin(PatientDataAdminMixin, BaseModelAdmin):
    list_display = ("id", "patient", "scope", "status_badge", "granted_by", "granted_at", "revoked_at")
    list_filter = ("scope", ConsentStatusFilter)
    search_fields = ("patient__patient_code", "granted_by")
    list_select_related = ("patient",)
    ordering = ("-granted_at", "-id")
    actions = ("revoke_selected",)

    @display(description="Status", ordering="revoked_at", label={"Active": "success", "Revoked": "warning"})
    def status_badge(self, obj):
        return "Active" if obj.revoked_at is None else "Revoked"

    def has_revoke_permission(self, request):
        return _can_change_access(request)

    @admin.action(description="Revoke selected consents (also switches off what rests on them)",
                  permissions=["revoke"])
    def revoke_selected(self, request, queryset):
        pairs = list(queryset.filter(revoked_at__isnull=True).values_list("id", "patient_id"))
        done = 0
        for consent_id, patient_id in pairs:
            try:
                with transaction.atomic():
                    patient = Patient.objects.select_for_update().get(pk=patient_id)
                    consent, effects = services.revoke_consent(patient, consent_id)
                    if effects is not None:
                        audit.record(request, audit.CONSENT_CHANGE, patient=patient, obj=consent, change="revoked",
                                     scope=consent.scope, via="admin", **effects)
                        done += 1
            except NotFound:
                continue
        self.message_user(request, f"{done} consent(s) revoked.", messages.SUCCESS if done else messages.INFO)

    def has_add_permission(self, request):
        return False

    def has_change_permission(self, request, obj=None):
        return False

    def has_delete_permission(self, request, obj=None):
        return False


# ------------------------------------------------------------------------------------------------ family links
@admin.register(FamilyLink)
class FamilyLinkAdmin(PatientDataAdminMixin, BaseModelAdmin):
    list_display = ("id", "patient", "family_user", "relationship", "access_badge", "consent_id")
    list_filter = ("is_active",)
    search_fields = ("patient__patient_code", "family_user__email")
    list_select_related = ("patient", "family_user", "consent")
    ordering = ("-id",)
    actions = ("switch_off_selected",)

    @display(description="Access", label={"On": "success", "Off": "warning"})
    def access_badge(self, obj):
        on = obj.is_active and obj.consent.revoked_at is None and obj.consent.scope == services.FAMILY_SCOPE
        return "On" if on else "Off"

    def has_switch_off_permission(self, request):
        return _can_change_access(request)

    @admin.action(description="Switch off access of selected family links", permissions=["switch_off"])
    def switch_off_selected(self, request, queryset):
        pairs = list(queryset.filter(is_active=True).values_list("id", "patient_id"))
        done = 0
        for link_id, patient_id in pairs:
            try:
                with transaction.atomic():
                    patient = Patient.objects.select_for_update().get(pk=patient_id)
                    link = services.unlink_family_member(patient, link_id)
                    audit.record(request, audit.FAMILY_LINK, patient=patient, obj=link, op="unlink", via="admin",
                                 family_user_id=link.family_user_id)
                    done += 1
            except NotFound:
                continue
        self.message_user(request, f"{done} family link(s) switched off.", messages.SUCCESS if done else messages.INFO)

    def has_add_permission(self, request):
        return False

    def has_change_permission(self, request, obj=None):
        return False

    def has_delete_permission(self, request, obj=None):
        return False